; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if9_e_go:			ld sp, if9_e
			jp ntc_xn
if10_e_go:			ld sp, if10_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 40
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 40
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
			xor a
			ld (de), a
p_chks_si1_e:
			ld (p_chks_rs), sp
			ld sp, p_chks
			jp ntc_xn
p_chks_r:		; end of chks
			ld sp, (p_chks_rs)
			jp ntc_xn
p_sumof_c:		; call sumof (normal)
			pop hl			; v() descriptor
			ld de, pa_sumof_v
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_sumof_sumof), hl
			ld hl, 0
			ld (var_sumof_n), hl
			ld (p_sumof_rs), sp
			ld sp, p_sumof
			jp ntc_xn
p_sumof_r:		; end of sumof
			ld sp, (p_sumof_rs)
			jp ntc_xn
p_fresh_c:		; call fresh (normal)
			ld hl, 0
			ld (var_fresh_fresh), hl
			ld hl, arr_fresh_b		; clear b()
			ld (hl), 0
			ld de, arr_fresh_b+1
			ld bc, 7
			ldir
			ld (p_fresh_rs), sp
			ld sp, p_fresh
			jp ntc_xn
p_fresh_r:		; end of fresh
			ld sp, (p_fresh_rs)
			jp ntc_xn
p_kept_c:		; call kept (normal)
			ld hl, 0
			ld (var_kept_kept), hl
			ld (p_kept_rs), sp
			ld sp, p_kept
			jp ntc_xn
p_kept_r:		; end of kept
			ld sp, (p_kept_rs)
			jp ntc_xn
p_totalx_c:		; call totalx (normal)
			pop hl			; a().x descriptor
			ld de, pa_totalx_a_x
			ld bc, 12
			ldir
			pop hl			; a().name descriptor
			ld de, pa_totalx_a_name
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_totalx_totalx), hl
			ld hl, 0
			ld (var_totalx_k), hl
			ld (p_totalx_rs), sp
			ld sp, p_totalx
			jp ntc_xn
p_totalx_r:		; end of totalx
			ld sp, (p_totalx_rs)
			jp ntc_xn
p_names_c:		; call names (normal)
			pop hl			; a().x descriptor
			ld de, pa_names_a_x
			ld bc, 12
			ldir
			pop hl			; a().name descriptor
			ld de, pa_names_a_name
			ld bc, 12
			ldir
			xor a
			ld (var_names_names), a
			ld (p_names_rs), sp
			ld sp, p_names
			jp ntc_xn
p_names_r:		; end of names
			ld sp, (p_names_rs)
			jp ntc_xn
p_bumpx_c:		; call bumpx (normal)
			pop hl			; a().x descriptor
			ld de, pa_bumpx_a_x
			ld bc, 12
			ldir
			pop hl			; a().name descriptor
			ld de, pa_bumpx_a_name
			ld bc, 12
			ldir
			ld (p_bumpx_rs), sp
			ld sp, p_bumpx
			jp ntc_xn
p_bumpx_r:		; end of bumpx
			ld sp, (p_bumpx_rs)
			jp ntc_xn
p_bag_item_get_c:		; call item (normal)
			pop hl			; i
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_bag_item_get_i), de
			ld hl, 0
			ld (var_bag_item_get_item), hl
			ld (p_bag_item_get_rs), sp
			ld sp, p_bag_item_get
			jp ntc_xn
p_bag_item_get_r:		; end of item
			ld sp, (p_bag_item_get_rs)
			jp ntc_xn
p_bag_item_let_c:		; call item (normal)
